package androidwacontacts_test

import (
	"crypto/sha256"
	"encoding/hex"
	"path/filepath"
	"strings"
	"testing"

	"github.com/rbenzing/minutiae/internal/parsers/parsertest"
)

// The fixtures of plan 4I task 12: generated by tools/fixtures/whatsapp_wadb.py, committed, pinned by hash.
const (
	remoteLive       = "/data/data/com.whatsapp/databases/wa.db"
	remoteCurrent    = "/data/user/0/com.whatsapp/databases/wa.db"
	remoteBusiness   = "/data/data/com.whatsapp.w4b/databases/wa.db"
	remoteBackup     = "/sdcard/WhatsApp/Databases/wa.db"
	remoteCrypt15    = "/sdcard/WhatsApp/Databases/wa.db.crypt15"
	remoteOtherPlace = "/storage/emulated/0/Android/data/com.whatsapp/databases/wa.db"
)

var variants = []string{
	"wa-2.11", "wa-current", "wa-business", "wa-no-table", "wa-backup-plain", "wa-crypt15", "wa-other-location", "wa-deleted",
}

// remoteFor is where the variant's database sits on the device.
func remoteFor(variant string) string {
	switch variant {
	case "wa-current", "wa-deleted":
		return remoteCurrent
	case "wa-business":
		return remoteBusiness
	case "wa-backup-plain":
		return remoteBackup
	case "wa-crypt15":
		return remoteCrypt15
	case "wa-other-location":
		return remoteOtherPlace
	}
	return remoteLive
}

func TestFixturesArePinnedByHash(t *testing.T) {
	seen := map[string]bool{}
	for _, v := range variants {
		fx := parsertest.LoadFixture(t, "testdata", v)
		for role, data := range fx.Files {
			sum := sha256.Sum256(data)
			key := v + "." + role
			seen[key] = true
			if want, ok := fixturePins[key]; !ok || want != hex.EncodeToString(sum[:]) {
				t.Errorf("%s: sha256 %x is not the pinned value %q (regenerate image, oracle and pin together)", key, sum, want)
			}
		}
	}
	for key := range fixturePins {
		if !seen[key] {
			t.Errorf("pin %s has no fixture file", key)
		}
	}
}

func TestEveryCommittedFixtureIsInTheVariantList(t *testing.T) {
	all, err := filepath.Glob("testdata/*.expect.json")
	if err != nil {
		t.Fatal(err)
	}
	var m []string
	for _, p := range all {
		if !strings.HasSuffix(p, ".recover.expect.json") { // the typed recovery oracles come with the parser (task 13)
			m = append(m, p)
		}
	}
	if len(m) != len(variants) {
		t.Errorf("%d fixtures on disk, %d in the variant list", len(m), len(variants))
	}
	for _, p := range m {
		name := strings.TrimSuffix(filepath.Base(p), ".expect.json")
		known := false
		for _, v := range variants {
			known = known || v == name
		}
		if !known {
			t.Errorf("testdata/%s is not in the variant list", name)
		}
	}
}
